   353	/// Detect a `cat > file <<'EOF'` or `cat >> file <<'EOF'` write in a shell
   354	/// command string. Returns `(file_path, lines_added, lines_removed)` on success.
   355	fn parse_exec_cmd_write(cmd: &str, file_cache: &HashMap<String, String>) -> Option<(String, i64, i64)> {
   356	    let cmd = cmd.trim();
   357	    if !cmd.starts_with("cat ") {
   358	        return None;
   359	    }
   360	    let after_cat = cmd[4..].trim_start();
   361	
   362	    // Locate the heredoc marker ("<<")
   363	    let heredoc_pos = after_cat.find("<<")?;
   364	    let redirect_and_path = after_cat[..heredoc_pos].trim();
   365	
   366	    // Extract file path from `> /path` or `>> /path`
   367	    let file_path = if redirect_and_path.starts_with(">>") {
   368	        redirect_and_path[2..].trim()
   369	    } else if redirect_and_path.starts_with('>') {
   370	        redirect_and_path[1..].trim()
   371	    } else {
   372	        return None;
   373	    };
   374	    if file_path.is_empty() {
   375	        return None;
   376	    }
   377	
   378	    // Determine heredoc end-marker (strip quotes: 'EOF' or "EOF" → EOF)
   379	    let raw_marker = after_cat[heredoc_pos + 2..].lines().next().unwrap_or("EOF");
   380	    let marker = raw_marker.trim().trim_matches('\'').trim_matches('"');
   381	
   382	    // Content is everything after the first newline, up to the closing marker line
   383	    let newline_pos = cmd.find('\n')?;
   384	    let body = &cmd[newline_pos + 1..];
   385	    let end_pat = format!("\n{}", marker);
   386	    let content = if let Some(end) = body.rfind(end_pat.as_str()) {
   387	        &body[..end]
   388	    } else {
   389	        body
   390	    };

