   175	        let dir_path = entry.path();
   176	        if !dir_path.is_dir() {
   177	            continue;
   178	        }
   179	
   180	        let entries_json = dir_path.join("entries.json");
   181	        let raw = match std::fs::read_to_string(&entries_json) {
   182	            Ok(s) => s,
   183	            Err(_) => continue,
   184	        };
   185	
   186	        #[derive(Deserialize)]
   187	        struct EntriesFile {
   188	            resource: Option<String>,
   189	            #[serde(default)]
   190	            entries: Vec<RawEntry>,
   191	        }
   192	
   193	        #[derive(Deserialize)]
   194	        struct RawEntry {
   195	            id: Option<String>,
   196	            source: Option<String>,
   197	            timestamp: Option<i64>,
   198	        }
   199	
   200	        let parsed: EntriesFile = match serde_json::from_str(&raw) {
   201	            Ok(p) => p,
   202	            Err(_) => continue,
   203	        };
   204	
   205	        let resource = match parsed.resource {
   206	            Some(r) => r,
   207	            None => continue,
   208	        };
   209	
   210	        // Strip "file://" prefix to get a plain absolute path
   211	        let file_path = if let Some(p) = resource.strip_prefix("file://") {
   212	            p.to_string()
   213	        } else {
   214	            resource
   215	        };
   216	
   217	        let mut entries: Vec<HistoryEntry> = parsed
   218	            .entries
   219	            .into_iter()
   220	            .filter_map(|e| {
   221	                Some(HistoryEntry {
   222	                    id: e.id?,
   223	                    source: e.source.unwrap_or_default(),
   224	                    timestamp: e.timestamp.unwrap_or(0),
   225	                    dir_path: dir_path.clone(),
   226	                })
   227	            })
   228	            .collect();
   229	
   230	        // Sort ascending by timestamp so we can find the "next" entry easily
   231	        entries.sort_by_key(|e| e.timestamp);
   232	
   233	        index
   234	            .entry(file_path)
   235	            .or_default()
   236	            .extend(entries);
   237	    }
