   239	    // Sort each file's entries by timestamp after merging (shouldn't have multiple
   240	    // dirs per file in practice, but be safe)
   241	    for v in index.values_mut() {
   242	        v.sort_by_key(|e| e.timestamp);
   243	    }
   244	
   245	    index
   246	}
