   405	// ── LOC from File History ─────────────────────────────────────────────────────
   406	
   407	fn loc_from_history(
   408	    file_path: &str,
   409	    session_start_ms: i64,
   410	    session_end_ms: i64,
   411	    index: &HistoryIndex,
   412	) -> (i64, i64) {
   413	    let entries = match index.get(file_path) {
   414	        Some(e) => e,
   415	        None => return (0, 0),
   416	    };
   417	
   418	    let mut total_added = 0i64;
   419	    let mut total_removed = 0i64;
   420	
   421	    for (i, entry) in entries.iter().enumerate() {
   422	        // Only consider "Undo *" entries (before-states) within the session range
   423	        if !entry.source.starts_with("Undo") {
   424	            continue;
   425	        }
   426	        if entry.timestamp < session_start_ms || entry.timestamp > session_end_ms {
   427	            continue;
   428	        }
   429	
   430	        // before-state
   431	        let before_path = entry.dir_path.join(&entry.id);
   432	        let before_content = std::fs::read_to_string(&before_path).unwrap_or_default();
   433	
   434	        // after-state: next entry in the sorted list
   435	        let after_content = if let Some(next) = entries.get(i + 1) {
   436	            let after_path = next.dir_path.join(&next.id);
   437	            std::fs::read_to_string(&after_path).unwrap_or_default()
   438	        } else {
   439	            String::new()
   440	        };
   441	
   442	        let (added, removed) = diff_line_counts(&before_content, &after_content);
   443	        total_added += added;
   444	        total_removed += removed;
   445	    }
   446	
   447	    (total_added, total_removed)
   448	}
