   523	/// Return the common ancestor directory of all file paths referenced in the
   524	/// composer context. Falls back to the first `codeBlockData` key on failure.
   525	fn extract_project_path(data: &ComposerData) -> Option<String> {
   526	    let mut paths: Vec<String> = Vec::new();
   527	
   528	    if let Some(ctx) = &data.context {
   529	        for sel in &ctx.file_selections {
   530	            if let Some(uri) = &sel.uri {
   531	                if let Some(p) = &uri.fs_path {
   532	                    paths.push(p.clone());
   533	                }
   534	            }
   535	        }
   536	    }
