   554	        for key in data.code_block_data.keys() {
   555	            paths.push(strip_file_scheme(key));
   556	        }
   557	    }
   558	
   559	    if paths.is_empty() {
   560	        return None;
   561	    }
   562	
   563	    // Find common ancestor by splitting on '/'
   564	    let split: Vec<Vec<&str>> = paths.iter().map(|p| p.split('/').collect()).collect();
   565	    let min_len = split.iter().map(|s| s.len()).min().unwrap_or(0);
   566	    let mut common: Vec<&str> = Vec::new();
   567	    for i in 0..min_len {
   568	        let seg = split[0][i];
   569	        if split.iter().all(|s| s[i] == seg) {
   570	            common.push(seg);
   571	        } else {
   572	            break;
   573	        }
   574	    }
   575	
   576	    let raw = if common.is_empty() {
   577	        paths[0].clone()
   578	    } else {
   579	        common.join("/")
   580	    };
   581	    Some(find_project_root(&raw))
