   584	fn find_project_root(path: &str) -> String {
   585	    const MARKERS: &[&str] = &[
   586	        ".git", "package.json", "Cargo.toml", "pyproject.toml", "go.mod",
   587	    ];
   588	    let p = std::path::Path::new(path);
   589	    // If the path has an extension treat it as a file; start from its parent
   590	    let mut dir = if p.extension().is_some() {
   591	        p.parent().unwrap_or(p)
   592	    } else {
   593	        p
   594	    };
   595	    loop {
   596	        if MARKERS.iter().any(|m| dir.join(m).exists()) {
   597	            return dir.to_string_lossy().into_owned();
   598	        }
   599	        match dir.parent() {
   600	            Some(parent) if parent != dir => dir = parent,
   601	            _ => break,
   602	        }
   603	    }
   604	    // Fallback: return the directory we started from
   605	    if p.extension().is_some() {
   606	        p.parent().unwrap_or(p).to_string_lossy().into_owned()
   607	    } else {
   608	        path.to_string()
   609	    }
   610	}
