            provider: self.provider_id().to_string(),
            session_id: sid,
            source_file,
            session_cwd,
            started_at,
            last_seen_at,
        })?;

        for event in &events {
            sink.on_event(event.clone())?;
        }

        Ok(ParseStats {
            sessions: 1,
            events: events.len(),
        })
    }
