use anyhow::{Result, bail};
use chrono::{DateTime, NaiveDate, TimeZone, Utc};
use rusqlite::Connection;
use std::collections::HashMap;
use std::time::UNIX_EPOCH;

use crate::change_intel::parsers::exec_heredoc::ExecHeredocWriteParser;
use crate::change_intel::providers;
use crate::change_intel::session_context::SessionContext;
use crate::change_intel::storage;
use crate::change_intel::types::{
    ParseStats, PatternParser, ProviderAdapter, ProviderCapability, SessionInfo, ToolCallEvent,
    ToolCallSink,
};

#[derive(Debug, Clone)]
pub struct IngestChangesOptions {
    pub provider: String,
    pub since: Option<String>,
}

#[derive(Debug, Clone, Default)]
pub struct IngestSummary {
    pub providers_processed: usize,
    pub sources_total: usize,
    pub sources_skipped: usize,
    pub sessions_seen: usize,
    pub events_seen: usize,
    pub ops_upserted: usize,
    pub parse_errors: usize,
}

struct IngestSink<'a> {
    conn: &'a Connection,
    parsers: Vec<Box<dyn PatternParser>>,
    contexts: HashMap<String, SessionContext>,
    since_dt: Option<DateTime<Utc>>,
    verbose: bool,
    ops_upserted: usize,
    parse_errors: usize,
}

impl<'a> IngestSink<'a> {
    fn new(conn: &'a Connection, since_dt: Option<DateTime<Utc>>, verbose: bool) -> Self {
        Self {
            conn,
            parsers: vec![Box::new(ExecHeredocWriteParser)],
            contexts: HashMap::new(),
            since_dt,
            verbose,
            ops_upserted: 0,
            parse_errors: 0,
        }
    }

}

fn capability_name(cap: ProviderCapability) -> &'static str {
    match cap {
        ProviderCapability::ExactPatch => "exact_patch",
        ProviderCapability::ShellHeredocWrites => "shell_heredoc_writes",
        ProviderCapability::SnapshotHistory => "snapshot_history",
        ProviderCapability::PromptOnly => "prompt_only",
    }
}

fn should_include_ts(ts: Option<&str>, since: Option<&DateTime<Utc>>) -> bool {
    let Some(since) = since else {
        return true;
    };

    let Some(ts) = ts else {
        return true;
    };

    if let Ok(parsed) = DateTime::parse_from_rfc3339(ts) {
        return parsed.with_timezone(&Utc) >= *since;
    }

    true
}

impl ToolCallSink for IngestSink<'_> {
    fn on_session(&mut self, session: SessionInfo) -> Result<()> {
        storage::upsert_change_session(self.conn, &session)?;
        self.contexts.entry(session.session_id.clone()).or_insert_with(|| {
            SessionContext::new(session.session_cwd)
        });
        Ok(())
    }

    fn on_event(&mut self, event: ToolCallEvent) -> Result<()> {
        let since_dt = self.since_dt.as_ref().cloned();
        let verbose = self.verbose;
        let ctx = self.contexts.entry(event.session_id.clone()).or_insert_with(|| {
            SessionContext::new(None)
        });

        for parser in &self.parsers {
            let outcome = parser.parse(&event, ctx);

            for err in outcome.errors {
                if verbose {
                    eprintln!(
                        "[change-intel] {} {} {}",
                        parser.name(),
                        event.call_id,
                        err.error
                    );
                }
                storage::insert_parse_error(self.conn, &err)?;
                self.parse_errors += 1;
            }

            for op in outcome.ops {
                if !should_include_ts(op.timestamp.as_deref(), since_dt.as_ref()) {
                    continue;
                }

                let op_id = storage::upsert_change_op(self.conn, &op)?;
                storage::replace_line_hashes(self.conn, op_id, &op.line_hashes)?;
                self.ops_upserted += 1;
            }
        }

        Ok(())
    }
}

fn parse_since(since: Option<&str>) -> Result<Option<DateTime<Utc>>> {
    let Some(raw) = since else {
        return Ok(None);
    };

    if let Ok(dt) = DateTime::parse_from_rfc3339(raw) {
        return Ok(Some(dt.with_timezone(&Utc)));
    }

    if let Ok(date) = NaiveDate::parse_from_str(raw, "%Y-%m-%d") {
        let dt = Utc
            .from_local_datetime(&date.and_hms_opt(0, 0, 0).ok_or_else(|| anyhow::anyhow!("invalid date"))?)
            .single()
            .ok_or_else(|| anyhow::anyhow!("invalid date conversion"))?;
        return Ok(Some(dt));
    }

    bail!("Invalid --since format. Use RFC3339 or YYYY-MM-DD")
}

fn file_signature(path: &std::path::Path) -> Result<Option<(i64, i64)>> {
    if !path.is_file() {
        return Ok(None);
    }

    let md = std::fs::metadata(path)?;
    let size = md.len() as i64;
    let mtime = md
        .modified()?
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs() as i64;

    Ok(Some((mtime, size)))
}

pub fn ingest_changes(conn: &Connection, options: IngestChangesOptions, verbose: bool) -> Result<IngestSummary> {
    ingest_with_adapters(conn, options, verbose, providers::registry())
}

pub fn ingest_with_adapters(
    conn: &Connection,
    options: IngestChangesOptions,
    verbose: bool,
    adapters: Vec<Box<dyn ProviderAdapter>>,
) -> Result<IngestSummary> {
    let provider = options.provider.to_ascii_lowercase();
    let since_dt = parse_since(options.since.as_deref())?;

    let selected: Vec<Box<dyn ProviderAdapter>> = if provider == "all" {
        adapters
    } else {
        adapters
            .into_iter()
            .filter(|a| a.provider_id() == provider)
            .collect()
    };

    if selected.is_empty() {
        bail!("Unknown provider '{}'. Use codex|cursor|claude|all", options.provider);
    }

    let mut summary = IngestSummary::default();

    for adapter in selected {
        summary.providers_processed += 1;

        if verbose {
            let caps = adapter
                .capabilities()
                .iter()
                .map(|c| capability_name(*c))
                .collect::<Vec<_>>()
                .join(",");
            eprintln!("[change-intel] provider={}", adapter.provider_id());
            eprintln!("[change-intel] capabilities={}", caps);
        }

        let mut sink = IngestSink::new(conn, since_dt, verbose);
        let sources = adapter.discover_sources()?;

        for source in sources {
            summary.sources_total += 1;
            let source_file = source.path.to_string_lossy().to_string();

            let sig = file_signature(&source.path)?;
            if let Some((mtime, size)) = sig {
                let cursor = storage::get_ingest_cursor(conn, adapter.provider_id(), &source_file)?;
                if let Some(cursor) = cursor {
                    if cursor.file_mtime == mtime && cursor.file_size == size {
                        summary.sources_skipped += 1;
                        continue;
                    }
                }
            }

            let stats: ParseStats = adapter.parse_source(&source, &mut sink)?;
            summary.sessions_seen += stats.sessions;
            summary.events_seen += stats.events;

            if let Some((mtime, size)) = sig {
                storage::upsert_ingest_cursor(conn, adapter.provider_id(), &source_file, mtime, size)?;
            }
        }

        summary.ops_upserted += sink.ops_upserted;
        summary.parse_errors += sink.parse_errors;
    }

    Ok(summary)
}

