use anyhow::Result;

use crate::change_intel::storage::{self, ChangeOpQuery};
use crate::db;

pub fn run(
    provider: Option<String>,
    session: Option<String>,
    path: Option<String>,
    limit: usize,
) -> Result<()> {
    let db = db::open()?;

    let rows = storage::query_change_ops(
        &db,
        &ChangeOpQuery {
            provider,
            session_id: session,
            path,
            limit,
        },
    )?;

    if rows.is_empty() {
        println!("No change ops found.");
        return Ok(());
    }

    println!(
        "{:<8}  {:<8}  {:<8}  {:<7}  {:>6}  {:>6}  {:<6}  {:<10}  {:<16}  {}",
        "Provider", "Session", "Call", "Mode", "+Lines", "-Lines", "Before", "Parser", "Timestamp", "Path"
    );
    println!(
        "{0:─<8}  {0:─<8}  {0:─<8}  {0:─<7}  {0:─>6}  {0:─>6}  {0:─<6}  {0:─<10}  {0:─<16}  {0:─<20}",
        ""
    );

    for row in rows {
        let session_short = &row.session_id[..row.session_id.len().min(8)];
        let call_short = &row.call_id[..row.call_id.len().min(8)];
        let path = row.rel_path.as_deref().unwrap_or(&row.abs_path);
        let ts = row
            .timestamp
            .as_deref()
            .unwrap_or("?")
            .chars()
            .take(16)
            .collect::<String>();

        println!(
            "{:<8}  {:<8}  {:<8}  {:<7}  {:>6}  {:>6}  {:<6}  {:<10}  {:<16}  {}",
            row.provider,
            session_short,
            call_short,
            row.write_mode,
            row.added_lines,
            row.removed_lines,
            if row.before_known { "yes" } else { "no" },
            format!("{}:{}", row.parser_name, row.parser_version),
            ts,
            path
        );
    }

    Ok(())
}

