    fn parse_source(&self, source: &SourceRef, sink: &mut dyn ToolCallSink) -> Result<ParseStats> {
        let file = File::open(&source.path)?;
        let reader = BufReader::new(file);

        let source_file = source.path.to_string_lossy().to_string();

        let mut session_id: Option<String> = None;
        let mut session_cwd: Option<String> = None;
        let mut started_at: Option<String> = None;
        let mut last_seen_at: Option<String> = None;

        let mut events: Vec<ToolCallEvent> = Vec::new();
        let mut output_by_call: HashMap<String, String> = HashMap::new();

        for line_result in reader.lines() {
            let raw = line_result?;
            if raw.trim().is_empty() {
                continue;
            }

            let parsed: Value = match serde_json::from_str(&raw) {
                Ok(v) => v,
                Err(_) => continue,
            };

            let timestamp = parsed
                .get("timestamp")
                .and_then(|v| v.as_str())
                .map(ToOwned::to_owned);
            if let Some(ts) = &timestamp {
                if last_seen_at.as_ref().map(|s| ts > s).unwrap_or(true) {
                    last_seen_at = Some(ts.clone());
                }
            }

            match parsed.get("type").and_then(|v| v.as_str()) {
                Some("session_meta") => {
                    if let Some(payload) = parsed.get("payload") {
                        session_id = payload
                            .get("id")
                            .and_then(|v| v.as_str())
                            .map(ToOwned::to_owned);
                        session_cwd = payload
                            .get("cwd")
                            .and_then(|v| v.as_str())
                            .map(ToOwned::to_owned);
                        started_at = payload
                            .get("timestamp")
                            .and_then(|v| v.as_str())
                            .map(ToOwned::to_owned)
                            .or_else(|| timestamp.clone());
                    }
                }
                Some("response_item") => {
                    let Some(payload) = parsed.get("payload") else {
                        continue;
                    };

                    let payload_type = payload.get("type").and_then(|v| v.as_str());
                    match payload_type {
                        Some("function_call") => {
                            let Some(name) = payload.get("name").and_then(|v| v.as_str()) else {
                                continue;
                            };
                            let Some(call_id) = payload.get("call_id").and_then(|v| v.as_str()) else {
                                continue;
                            };
                            let Some(sid) = session_id.clone() else {
                                continue;
                            };

                            let input_json = payload
                                .get("arguments")
                                .map(|v| v.to_string())
                                .unwrap_or_else(|| "null".to_string());

                            events.push(ToolCallEvent {
                                provider: self.provider_id().to_string(),
                                session_id: sid,
                                source_file: source_file.clone(),
                                timestamp: timestamp.clone(),
                                call_id: call_id.to_string(),
                                tool_name: name.to_string(),
                                input_json,
                                output_json: None,
                            });
                        }
                        Some("function_call_output") => {
                            let Some(call_id) = payload.get("call_id").and_then(|v| v.as_str()) else {
                                continue;
                            };
                            output_by_call.insert(call_id.to_string(), payload.to_string());
                        }
                        _ => {}
                    }
                }
                _ => {}
            }
        }

        let Some(sid) = session_id else {
            return Ok(ParseStats::default());
        };

        for event in &mut events {
            if let Some(output) = output_by_call.get(&event.call_id) {
                event.output_json = Some(output.clone());
            }
        }

        sink.on_session(SessionInfo {
            provider: self.provider_id().to_string(),
            session_id: sid,
            source_file,
            session_cwd,
            started_at,
            last_seen_at,
        })?;

        for event in &events {
            sink.on_event(event.clone())?;
        }

        Ok(ParseStats {
            sessions: 1,
            events: events.len(),
        })
    }
