pub fn query_change_ops(conn: &Connection, q: &ChangeOpQuery) -> Result<Vec<ChangeOpRow>> {
    let mut sql = String::from(
        "SELECT provider, session_id, call_id, timestamp, abs_path, rel_path,
                write_mode, before_known, added_lines, removed_lines,
                parser_name, parser_version
         FROM change_ops
         WHERE 1=1",
    );

    let mut params_vec: Vec<SqlValue> = Vec::new();

    if let Some(provider) = &q.provider {
        sql.push_str(" AND provider = ?");
        params_vec.push(SqlValue::from(provider.clone()));
    }

    if let Some(session_id) = &q.session_id {
        sql.push_str(" AND session_id = ?");
        params_vec.push(SqlValue::from(session_id.clone()));
    }

    if let Some(path) = &q.path {
        sql.push_str(" AND (abs_path LIKE ? OR rel_path LIKE ?)");
        let like = format!("%{}%", path);
        params_vec.push(SqlValue::from(like.clone()));
        params_vec.push(SqlValue::from(like));
    }

    sql.push_str(" ORDER BY COALESCE(timestamp, created_at) DESC, id DESC LIMIT ?");
    params_vec.push(SqlValue::from(q.limit as i64));

    let mut stmt = conn.prepare(&sql)?;
    let rows = stmt.query_map(params_from_iter(params_vec.iter()), |row| {
        Ok(ChangeOpRow {
            provider: row.get(0)?,
            session_id: row.get(1)?,
            call_id: row.get(2)?,
            timestamp: row.get(3)?,
            abs_path: row.get(4)?,
            rel_path: row.get(5)?,
            write_mode: row.get(6)?,
            before_known: row.get::<_, i64>(7)? != 0,
            added_lines: row.get(8)?,
            removed_lines: row.get(9)?,
            parser_name: row.get(10)?,
            parser_version: row.get(11)?,
        })
    })?;

    let mut out = Vec::new();
    for row in rows {
        out.push(row?);
    }
    Ok(out)
}

