            let (marker, marker_end) = if bytes[k] as char == '\'' || bytes[k] as char == '"' {
                let quote = bytes[k] as char;
                let mut end = k + 1;
                while end < cmd.len() && bytes[end] as char != quote {
                    end += 1;
                }
                if end >= cmd.len() {
