   549	            added_lines.extend(parse_string_array(Some(added)));
   550	        }
   551	        if let Some(removed) = fate_obj.get("removedLines") {
   552	            removed_lines.extend(parse_string_array(Some(removed)));
   553	        }
   554	    }
   555	
   556	    if added_lines.is_empty() && removed_lines.is_empty() {
   557	        return Ok(None);
   558	    }
   559	
   560	    let mut line_hashes = hash_counts_for_lines(&added_lines, LineSide::Added);
   561	    line_hashes.extend(hash_counts_for_lines(&removed_lines, LineSide::Removed));
   562	
   563	    let abs_path_buf = PathBuf::from(abs_path);
   564	    let repo_root = detect_repo_root(&abs_path_buf);
   565	    let rel_path = to_rel_path(repo_root.as_deref(), &abs_path_buf);
