   622	fn extract_partial_targets(parsed: &Value) -> Vec<PartialTarget> {
   623	    let mut out: HashSet<PartialTarget> = HashSet::new();
   624	
   625	    let Some(code_block_data) = parsed.get("codeBlockData").and_then(|v| v.as_object()) else {
   626	        return Vec::new();
   627	    };
   628	
   629	    for (file_key, value) in code_block_data {
   630	        let entries: Vec<&Value> = if let Some(list) = value.as_array() {
   631	            list.iter().collect()
   632	        } else if let Some(map) = value.as_object() {
   633	            map.values().collect()
   634	        } else {
   635	            Vec::new()
   636	        };
   637	
   638	        for entry in entries {
   639	            let Some(entry_obj) = entry.as_object() else {
   640	                continue;
   641	            };
   642	            if entry_obj.get("status").and_then(|v| v.as_str()) != Some("accepted") {
   643	                continue;
   644	            }
   645	
   646	            let Some(partial_id) = entry_obj
   647	                .get("partialInlineDiffFatesId")
   648	                .and_then(|v| v.as_str())
   649	                .map(ToOwned::to_owned)
   650	            else {
   651	                continue;
   652	            };
   653	
   654	            let abs_path = entry_obj
   655	                .get("uri")
   656	                .and_then(extract_file_path_from_uri_value)
   657	                .or_else(|| extract_file_path_from_string(file_key));
   658	
   659	            let Some(abs_path) = abs_path else {
   660	                continue;
   661	            };
   662	
   663	            out.insert(PartialTarget {
   664	                partial_id,
   665	                abs_path,
   666	            });
   667	        }
   668	    }
   669	
   670	    out.into_iter().collect()
   671	}
