   729	fn extract_file_path_from_uri_value(uri: &Value) -> Option<String> {
   730	    match uri {
   731	        Value::Object(map) => {
   732	            if let Some(scheme) = map.get("scheme").and_then(|v| v.as_str()) {
   733	                if scheme != "file" {
   734	                    return None;
   735	                }
   736	            }
   737	
   738	            if let Some(fs_path) = map.get("fsPath").and_then(|v| v.as_str()) {
   739	                return Some(fs_path.to_string());
   740	            }
   741	
   742	            if let Some(external) = map.get("external").and_then(|v| v.as_str()) {
   743	                return extract_file_path_from_string(external);
   744	            }
   745	
   746	            if let Some(path) = map.get("path").and_then(|v| v.as_str()) {
   747	                return Some(path.to_string());
   748	            }
   749	
   750	            None
   751	        }
   752	        Value::String(s) => extract_file_path_from_string(s),
   753	        _ => None,
   754	    }
   755	}
