   757	fn extract_file_path_from_string(raw: &str) -> Option<String> {
   758	    if raw.starts_with("file://") {
   759	        return Some(strip_file_scheme(raw));
   760	    }
   761	    if raw.starts_with("vscode-notebook-cell:") {
   762	        return None;
   763	    }
   764	    if raw.contains("://") {
   765	        return None;
   766	    }
   767	    Some(raw.to_string())
   768	}
