   778	fn file_signature(path: &Path) -> Result<Option<(i64, i64)>> {
   779	    if !path.is_file() {
   780	        return Ok(None);
   781	    }
   782	
   783	    let md = std::fs::metadata(path)?;
   784	    let size = md.len() as i64;
   785	    let mtime = md
   786	        .modified()?
   787	        .duration_since(UNIX_EPOCH)
   788	        .unwrap_or_default()
   789	        .as_secs() as i64;
   790	
   791	    Ok(Some((mtime, size)))
   792	}
