#[derive(Debug, Clone, Default)]
pub struct ProviderCodeChangeSummary {
    pub provider: String,
    pub sources_discovered: usize,
    pub sources_skipped: usize,
    pub tool_calls_inspected: usize,
    pub ops_upserted: usize,
    pub parse_errors: usize,
}

#[derive(Debug, Clone, Default)]
