            }
        }
        return;
    }

    if name != "apply_patch" {
        return;
    }

    // Arguments is a JSON string: {"patch": "...diff..."}
    let args_str: Option<String> = value
        .get("arguments")
        .map(|v| match v {
            Value::String(s) => s.clone(),
            other => other.to_string(),
        });

    let patch = match args_str {
        Some(s) => {
            if let Ok(obj) = serde_json::from_str::<Value>(&s) {
                obj.get("patch")
                    .and_then(|p| p.as_str())
                    .unwrap_or(&s)
