+fn determine_commit_scope(
+    repo_root: &str,
+    head_sha: &str,
+    cursor: Option<&types::CommitCursor>,
+    ai_min_ts: &str,
+    options: &RunOptions,
+    conn: &Connection,
+) -> Result<Vec<String>> {
+    if options.recompute {
+        return list_commits_since(
+            repo_root,
+            ai_min_ts,
+            options.include_merges,
+            options.max_commits,
+        );
+    }
+
+    let Some(cursor) = cursor else {
+        return list_commits_since(
+            repo_root,
+            ai_min_ts,
+            options.include_merges,
+            options.max_commits,
+        );
+    };
+
+    if is_ancestor(repo_root, &cursor.last_head_sha, head_sha)? {
+        match list_commits_range(
+            repo_root,
+            &cursor.last_head_sha,
+            head_sha,
+            options.include_merges,
+            options.max_commits,
+        ) {
+            Ok(v) => return Ok(v),
+            Err(e) => {
+                insert_commit_assoc_error(
+                    conn,
+                    repo_root,
+                    None,
+                    "incremental_range",
+                    &e.to_string(),
+                )?;
+                return list_commits_since(
+                    repo_root,
+                    ai_min_ts,
+                    options.include_merges,
+                    options.max_commits,
