+fn normalize_path(path: &str) -> String {
+    let pb = PathBuf::from(path);
+    let abs = if pb.is_absolute() {
+        pb
+    } else if let Ok(cwd) = std::env::current_dir() {
+        cwd.join(pb)
+    } else {
+        PathBuf::from(path)
+    };
+
+    std::fs::canonicalize(&abs)
+        .unwrap_or(abs)
+        .to_string_lossy()
+        .to_string()
+}
