            Ok(v) => v,
            Err(e) => {
                repo_summary.errors += 1;
                summary.errors += 1;
                insert_commit_assoc_error(conn, &repo_root, None, "head_sha", &e.to_string())?;
                summary.repo_summaries.push(repo_summary);
                continue;
            }
