    files.sort_by(|a, b| a.rel_path.cmp(&b.rel_path));
    files
}

fn evaluate_file_match_for_path(
    availability_stmt: &mut rusqlite::Statement<'_>,
    repo_root: &str,
    target_path: &str,
    rows: &[CommitHashRow],
) -> Result<PathMatch> {
    let mut out = PathMatch::default();

    for row in rows {
        let avail = load_provider_availability(
            availability_stmt,
            repo_root,
            target_path,
            &row.side,
            &row.line_hash,
        )?;
        if avail.is_empty() {
            continue;
        }

        let avail_total: i64 = avail.values().sum();
        if avail_total <= 0 {
            continue;
        }

        let matched = row.count.min(avail_total);
        if matched <= 0 {
            continue;
        }

        if row.side == "+" {
            out.matched_added += matched;
        } else if row.side == "-" {
            out.matched_removed += matched;
        }

        let matched_f = matched as f64;
        let avail_total_f = avail_total as f64;
        for (provider, provider_avail) in avail {
            let contribution = matched_f * (provider_avail as f64 / avail_total_f);
            *out.provider_matched.entry(provider).or_insert(0.0) += contribution;
        }
    }

    Ok(out)
}

fn choose_fallback_alias_path(
    fallback_stmt: &mut rusqlite::Statement<'_>,
    repo_root: &str,
    commit_id: i64,
    strict_path: &str,
    rows: &[CommitHashRow],
    file_total_lines: i64,
    verbose: bool,
) -> Result<Option<(String, AliasTier)>> {
    if file_total_lines <= 0 {
        return Ok(None);
    }

    let mut scores: HashMap<String, i64> = HashMap::new();
    for row in rows {
        let path_avail = load_path_availability_candidates(
            fallback_stmt,
            repo_root,
            &row.side,
            &row.line_hash,
        )?;

        for (path, avail) in path_avail {
            if path == strict_path {
                continue;
            }
            let matched = row.count.min(avail);
            if matched > 0 {
                *scores.entry(path).or_insert(0) += matched;
            }
        }
    }

    if scores.is_empty() {
        return Ok(None);
    }

    let strict_base = basename(strict_path).to_string();
    let mut all_candidates: Vec<(String, i64)> = scores.into_iter().collect();
    all_candidates.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

    let mut filename_candidates: Vec<(String, i64)> = all_candidates
        .iter()
        .filter(|(path, _)| basename(path) == strict_base)
        .cloned()
        .collect();
    filename_candidates.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

    let filename_eval = evaluate_candidate_pool(&filename_candidates, file_total_lines);
    if verbose {
        log_pool_debug(
            "filename_pool",
            commit_id,
            strict_path,
            file_total_lines,
            &filename_candidates,
            &filename_eval,
            true,
        );
    }
    if let Some(eval) = filename_eval {
        if eval.accepted {
            return Ok(Some((eval.winner_path, AliasTier::Filename)));
        }
    }

    let repo_eval = evaluate_candidate_pool(&all_candidates, file_total_lines);
    if verbose {
        log_pool_debug(
            "repo_pool",
            commit_id,
            strict_path,
            file_total_lines,
            &all_candidates,
            &repo_eval,
            false,
        );
    }
    if let Some(eval) = repo_eval {
        if eval.accepted {
            return Ok(Some((eval.winner_path, AliasTier::Repo)));
        }
    }

    Ok(None)
}

fn evaluate_candidate_pool(candidates: &[(String, i64)], file_total_lines: i64) -> Option<PoolEval> {
    if candidates.is_empty() || file_total_lines <= 0 {
        return None;
    }

    let (winner_path, winner_matched) = &candidates[0];
    let runner_matched = candidates.get(1).map(|(_, m)| *m).unwrap_or(0);

    let winner_ratio = *winner_matched as f64 / file_total_lines as f64;
    let runner_ratio = runner_matched as f64 / file_total_lines as f64;
    let accepted = winner_ratio >= FALLBACK_MIN_RATIO
        && *winner_matched >= FALLBACK_MIN_MATCHED_LINES
        && (winner_ratio - runner_ratio) >= FALLBACK_WINNER_MARGIN;

    Some(PoolEval {
        winner_path: winner_path.clone(),
        winner_matched: *winner_matched,
        winner_ratio,
        runner_ratio,
        accepted,
    })
}

fn basename(path: &str) -> &str {
    path.rsplit('/').next().unwrap_or(path)
}

fn log_pool_debug(
    pool_name: &str,
    commit_id: i64,
    strict_path: &str,
    file_total_lines: i64,
    candidates: &[(String, i64)],
    eval: &Option<PoolEval>,
    print_all: bool,
) {
    eprintln!(
        "[commit-assoc][fallback-debug] commit_id={} file={} pool={} total_lines={} candidates={}",
        commit_id,
        strict_path,
        pool_name,
        file_total_lines,
        candidates.len()
    );

    let limit = if print_all { candidates.len() } else { candidates.len().min(8) };
    for (path, matched) in candidates.iter().take(limit) {
        let ratio = if file_total_lines > 0 {
            *matched as f64 / file_total_lines as f64
        } else {
            0.0
        };
        eprintln!(
            "[commit-assoc][fallback-debug] commit_id={} file={} pool={} candidate={} matched={} ratio={:.4}",
            commit_id, strict_path, pool_name, path, matched, ratio
        );
    }
    if !print_all && candidates.len() > limit {
        eprintln!(
            "[commit-assoc][fallback-debug] commit_id={} file={} pool={} ... {} more candidates omitted",
            commit_id,
            strict_path,
            pool_name,
            candidates.len() - limit
        );
    }

    match eval {
        Some(e) => {
            let margin = e.winner_ratio - e.runner_ratio;
            let ratio_ok = e.winner_ratio >= FALLBACK_MIN_RATIO;
            let lines_ok = e.winner_matched >= FALLBACK_MIN_MATCHED_LINES;
            let margin_ok = margin >= FALLBACK_WINNER_MARGIN;
            eprintln!(
                "[commit-assoc][fallback-debug] commit_id={} file={} pool={} winner={} winner_ratio={:.4} runner_ratio={:.4} margin={:.4} matched={} checks(ratio={}, lines={}, margin={}) accepted={}",
                commit_id,
                strict_path,
                pool_name,
                e.winner_path,
                e.winner_ratio,
                e.runner_ratio,
                margin,
                e.winner_matched,
                ratio_ok,
                lines_ok,
                margin_ok,
                e.accepted
            );
        }
        None => {
            eprintln!(
                "[commit-assoc][fallback-debug] commit_id={} file={} pool={} no candidates",
                commit_id, strict_path, pool_name
            );
        }
    }
}

#[derive(Debug, Clone, Copy)]
enum AliasTier {
    Filename,
    Repo,
}

fn load_provider_availability(
    stmt: &mut rusqlite::Statement<'_>,
    repo_root: &str,
    rel_path: &str,
    side: &str,
    line_hash: &str,
) -> Result<HashMap<String, i64>> {
    let rows = stmt.query_map(
        params![repo_root, rel_path, side, line_hash],
        |r| Ok((r.get::<_, String>(0)?, r.get::<_, i64>(1)?)),
    )?;

    let mut out = HashMap::new();
    for row in rows {
        let (provider, avail) = row?;
        out.insert(provider, avail);
    }
    Ok(out)
}

fn load_path_availability_candidates(
    stmt: &mut rusqlite::Statement<'_>,
    repo_root: &str,
    side: &str,
    line_hash: &str,
) -> Result<Vec<(String, i64)>> {
    let rows = stmt.query_map(params![repo_root, side, line_hash], |r| {
        Ok((r.get::<_, String>(0)?, r.get::<_, i64>(1)?))
    })?;

    let mut out = Vec::new();
    for row in rows {
        out.push(row?);
    }
    Ok(out)
}

