    let mut files: Vec<FileCommitRows> = grouped
        .into_iter()
        .map(|(rel_path, rows)| {
            let total_lines = rows.iter().map(|r| r.count).sum();
            FileCommitRows {
                rel_path,
                rows,
                total_lines,
            }
        })
        .collect();
    files.sort_by(|a, b| a.rel_path.cmp(&b.rel_path));
    files
}

