   189	fn group_commit_rows_by_path(rows: Vec<CommitHashRow>) -> Vec<FileCommitRows> {
   190	    let mut grouped: HashMap<String, Vec<CommitHashRow>> = HashMap::new();
   191	    for row in rows {
   192	        grouped.entry(row.rel_path.clone()).or_default().push(row);
   193	    }
   194	
   195	    let mut files: Vec<FileCommitRows> = grouped
   196	        .into_iter()
   197	        .map(|(rel_path, rows)| {
   198	            let total_lines = rows.iter().map(|r| r.count).sum();
   199	            FileCommitRows {
   200	                rel_path,
   201	                rows,
   202	                total_lines,
   203	            }
   204	        })
   205	        .collect();
   206	    files.sort_by(|a, b| a.rel_path.cmp(&b.rel_path));
