   210	fn evaluate_file_match_for_path(
   211	    availability_stmt: &mut rusqlite::Statement<'_>,
   212	    repo_root: &str,
   213	    target_path: &str,
   214	    rows: &[CommitHashRow],
   215	) -> Result<PathMatch> {
   216	    let mut out = PathMatch::default();
   217	
   218	    for row in rows {
   219	        let avail = load_provider_availability(
   220	            availability_stmt,
   221	            repo_root,
   222	            target_path,
   223	            &row.side,
   224	            &row.line_hash,
   225	        )?;
   226	        if avail.is_empty() {
   227	            continue;
   228	        }
   229	
   230	        let avail_total: i64 = avail.values().sum();
   231	        if avail_total <= 0 {
   232	            continue;
   233	        }
   234	
   235	        let matched = row.count.min(avail_total);
   236	        if matched <= 0 {
   237	            continue;
   238	        }
   239	
   240	        if row.side == "+" {
   241	            out.matched_added += matched;
   242	        } else if row.side == "-" {
   243	            out.matched_removed += matched;
   244	        }
   245	
   246	        let matched_f = matched as f64;
   247	        let avail_total_f = avail_total as f64;
   248	        for (provider, provider_avail) in avail {
   249	            let contribution = matched_f * (provider_avail as f64 / avail_total_f);
   250	            *out.provider_matched.entry(provider).or_insert(0.0) += contribution;
   251	        }
   252	    }
   253	
   254	    Ok(out)
   255	}
