   257	fn choose_fallback_alias_path(
   258	    fallback_stmt: &mut rusqlite::Statement<'_>,
   259	    repo_root: &str,
   260	    strict_path: &str,
   261	    rows: &[CommitHashRow],
   262	    file_total_lines: i64,
   263	) -> Result<Option<String>> {
   264	    if file_total_lines <= 0 {
   265	        return Ok(None);
   266	    }
   267	
   268	    let mut scores: HashMap<String, i64> = HashMap::new();
   269	    for row in rows {
   270	        let path_avail = load_path_availability_candidates(
   271	            fallback_stmt,
   272	            repo_root,
   273	            &row.side,
   274	            &row.line_hash,
   275	        )?;
   276	
   277	        for (path, avail) in path_avail {
   278	            if path == strict_path {
   279	                continue;
   280	            }
   281	            let matched = row.count.min(avail);
   282	            if matched > 0 {
   283	                *scores.entry(path).or_insert(0) += matched;
   284	            }
   285	        }
   286	    }
   287	
   288	    if scores.is_empty() {
   289	        return Ok(None);
   290	    }
   291	
   292	    let strict_base = basename(strict_path).to_string();
   293	    let mut all_candidates: Vec<(String, i64)> = scores.into_iter().collect();
   294	    all_candidates.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
   295	
   296	    let mut filename_candidates: Vec<(String, i64)> = all_candidates
   297	        .iter()
   298	        .filter(|(path, _)| basename(path) == strict_base)
   299	        .cloned()
   300	        .collect();
   301	    filename_candidates.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
   302	
   303	    if let Some(winner_path) = pick_confident_alias(&filename_candidates, file_total_lines) {
   304	        return Ok(Some(winner_path));
   305	    }
   306	
   307	    if let Some(winner_path) = pick_confident_alias(&all_candidates, file_total_lines) {
   308	        return Ok(Some(winner_path));
   309	    }
   310	
   311	    Ok(None)
   312	}
   313	
   314	fn pick_confident_alias(candidates: &[(String, i64)], file_total_lines: i64) -> Option<String> {
   315	    if candidates.is_empty() || file_total_lines <= 0 {
   316	        return None;
   317	    }
   318	
   319	    let (winner_path, winner_matched) = &candidates[0];
   320	    let runner_matched = candidates.get(1).map(|(_, m)| *m).unwrap_or(0);
   321	
   322	    let winner_ratio = *winner_matched as f64 / file_total_lines as f64;
   323	    let runner_ratio = runner_matched as f64 / file_total_lines as f64;
   324	    let accepted = winner_ratio >= FALLBACK_MIN_RATIO
   325	        && *winner_matched >= FALLBACK_MIN_MATCHED_LINES
   326	        && (winner_ratio - runner_ratio) >= FALLBACK_WINNER_MARGIN;
   327	    if accepted {
   328	        Some(winner_path.clone())
   329	    } else {
   330	        None
   331	    }
   332	}
   333	
   334	fn basename(path: &str) -> &str {
   335	    path.rsplit('/').next().unwrap_or(path)
   336	}
