    92	fn pipe_to_pager(output: &str) -> Result<()> {
    93	    use std::process::{Command, Stdio};
    94	
    95	    let pager = std::env::var("PAGER").unwrap_or_else(|_| "less".to_string());
    96	
    97	    let mut cmd = Command::new(&pager);
    98	    if pager == "less" || pager.ends_with("/less") {
    99	        // -R: pass ANSI codes through  -F: quit if output fits on one screen  -X: don't clear on exit
   100	        cmd.args(["-R", "-F", "-X"]);
   101	    }
   102	
   103	    match cmd.stdin(Stdio::piped()).spawn() {
   104	        Ok(mut child) => {
   105	            if let Some(mut stdin) = child.stdin.take() {
   106	                let _ = stdin.write_all(output.as_bytes());
   107	            }
   108	            child.wait()?;
   109	        }
   110	        Err(_) => print!("{}", output),
   111	    }
   112	    Ok(())
   113	}

