+        let Some(start) = line.find(needle) else {
+            continue;
+        };
+        let suffix = &line[start + needle.len()..];
+        let sha: String = suffix.chars().take_while(|c| c.is_ascii_hexdigit()).collect();
+        if sha.len() == 40 {
+            out.push(sha.to_lowercase());
+        }
+    }
