+        for file in diff.file_diffs {
+            for lh in file.line_hashes {
+                if lh.side == LineSide::Added {
+                    index.add_max(&file.rel_path, &lh.line_hash, lh.count);
+                }
+            }
+        }
+    }
+    Ok(index)
