+        for file in diff.file_diffs {
+            for lh in file.line_hashes {
+                if lh.side == LineSide::Removed {
+                    *out.entry((file.rel_path.clone(), lh.line_hash.clone()))
+                        .or_insert(0) += lh.count;
+                }
+            }
+        }
+    }
+    Ok(out)
