                    provider: "cursor".into(),
                    file_path: "__total__".into(),
                    lines_added: added,
                    lines_removed: removed,
                    timestamp: timestamp.clone(),
                });
            }
        }
    }

    let count = events.len();
    for event in &events {
        db::insert_event(db, event)?;
    }
    Ok(count)
