    if let Some(line) = first_error_line(user_text) {
        let signature = normalize_signature(line);
        if !signature.is_empty() {
            return Some(signature);
        }
    }

    let signature = normalize_signature(user_text);
    if signature.is_empty() {
        None
    } else {
        Some(signature)
    }
}

